    });
}

function attachDealListeners() {
    document.querySelectorAll('.deal-cta').forEach(btn => {
        btn.addEventListener('click', handleGetDeal);
    });
}

function handleAddToCart(e) {
    const productId = e.target.dataset.productId;
    updateCartCount();
    showNotification(`Product added to cart!`);
}

function handleGetDeal(e) {
    const dealId = e.target.dataset.dealId;
    updateCartCount();
    showNotification(`Deal added to cart! 🎉`);
}

function updateCartCount() {
    const cartCount = document.querySelector('.cart-count');
    const currentCount = parseInt(cartCount.textContent) || 0;
    cartCount.textContent = currentCount + 1;
}

function showNotification(message) {
    const notification = document.createElement('div');
    notification.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        background-color: #2ecc71;
        color: white;
        padding: 1rem 1.5rem;
        border-radius: 8px;
